const notes = new Map();
let counter = 0;

function nextId() {
  counter += 1;
  return `n${counter}`;
}

function textResult(text) {
  return { content: [{ type: 'text', text }] };
}

function fail(message) {
  throw new Error(message);
}

function requireString(args, field) {
  if (!args || typeof args !== 'object') fail(`Missing arguments`);
  const value = args[field];
  if (typeof value !== 'string' || value.length === 0) {
    fail(`Invalid or missing '${field}'`);
  }
  return value;
}

const tools = [
  {
    name: 'note_create',
    description: 'Create a new note with a title and body. Returns the generated note id.',
    inputSchema: {
      type: 'object',
      properties: {
        title: { type: 'string', description: 'Title of the note (non-empty).' },
        body: { type: 'string', description: 'Body of the note (non-empty).' },
      },
      required: ['title', 'body'],
      additionalProperties: false,
    },
  },
  {
    name: 'note_get',
    description: 'Retrieve a previously created note by its id.',
    inputSchema: {
      type: 'object',
      properties: {
        note_id: { type: 'string', description: 'The id of the note to retrieve.' },
      },
      required: ['note_id'],
      additionalProperties: false,
    },
  },
];

export async function listTools() {
  return tools;
}

export async function callTool(name, args) {
  if (name === 'note_create') {
    const title = requireString(args, 'title');
    const body = requireString(args, 'body');
    const id = nextId();
    notes.set(id, { id, title, body });
    return textResult(`Created note ${id}: ${title}`);
  }
  if (name === 'note_get') {
    const noteId = requireString(args, 'note_id');
    const note = notes.get(noteId);
    if (!note) fail(`Unknown note_id: ${noteId}`);
    return textResult(`Note ${note.id}\nTitle: ${note.title}\nBody: ${note.body}`);
  }
  fail(`Unknown tool: ${name}`);
}

